"""Assemble native conversion probes for SM100a and SM110a; CPU only."""

import hashlib
import json
import os
from pathlib import Path
import re
import subprocess

ROOT = Path(__file__).resolve().parent
TOOLS = ROOT.parent / "toolchain"
PTXAS = TOOLS / "cuda_nvcc-linux-sbsa-13.4.92-archive/bin/ptxas"
DISASM = TOOLS / "cuda_nvdisasm-linux-sbsa-13.4.92-archive/bin/nvdisasm"


def command(argv, stem):
    env = os.environ.copy()
    env["TMPDIR"] = str(ROOT / "tmp")
    result = subprocess.run([str(a) for a in argv], capture_output=True,
                            text=True, timeout=60, env=env, check=False)
    path = ROOT / "preparation" / stem
    path.with_suffix(".command.json").write_text(json.dumps({
        "argv": [str(a) for a in argv], "returncode": result.returncode,
    }, indent=2) + "\n")
    path.with_suffix(".stdout.txt").write_text(result.stdout)
    path.with_suffix(".stderr.txt").write_text(result.stderr)
    return result


PREFIX = """
.visible .entry NAME(
    .param .u64 inputs, .param .u64 outputs, .param .u32 count
) {
  .reg .pred %p;
  .reg .b8 %b<4>;
  .reg .b16 %h<8>;
  .reg .b32 %r<24>;
  .reg .b64 %rd<8>;
  ld.param.u64 %rd0, [inputs];
  ld.param.u64 %rd1, [outputs];
  ld.param.u32 %r0, [count];
  mov.u32 %r1, %ctaid.x;
  mov.u32 %r2, %ntid.x;
  mov.u32 %r3, %tid.x;
  mad.lo.u32 %r4, %r1, %r2, %r3;
  setp.ge.u32 %p, %r4, %r0;
  @%p bra DONE;
  mul.wide.u32 %rd2, %r4, 8;
  add.u64 %rd3, %rd0, %rd2;
  add.u64 %rd4, %rd1, %rd2;
  ld.global.v2.u32 {%r5, %r6}, [%rd3];
  cvt.u16.u32 %h0, %r5;
  mov.b16 {%b0, %b1}, %h0;
  mov.b32 {%h1, %h2}, %r6;
"""
SUFFIX = """
  st.global.v2.u32 [%rd4], {%r20, %r21};
DONE:
  ret;
}
"""


def decode(kind, fmt, first=10):
    source = ("%b0", "%b1") if kind == "e2m1" else ("%h1", "%h2")
    return "".join(f"  cvt.rn.{fmt}x2.{kind}x2 %r{first+i}, {src};\n"
                   for i, src in enumerate(source))


kernels = {}
for fmt in ("f16", "bf16"):
    for kind in ("e2m1", "e4m3"):
        kernels[f"Decode_{kind}_{fmt}"] = decode(kind, fmt, 20)
    kernels[f"Scaled_{fmt}"] = (
        decode("e2m1", fmt) + decode("e4m3", fmt, 12) +
        f"  mul.rn.{fmt}x2 %r14, %r10, %r12;\n" +
        f"  mul.rn.{fmt}x2 %r15, %r11, %r13;\n" +
        f"  cvt.rn.satfinite.e4m3x2.{fmt}x2 %h3, %r14;\n" +
        f"  cvt.rn.satfinite.e4m3x2.{fmt}x2 %h4, %r15;\n" +
        "  mov.b32 %r20, {%h3, %h4};\n  mov.u32 %r21, 0;\n")
kernels["Roundtrip_e2m1_f16"] = (
    decode("e2m1", "f16") +
    "  cvt.rn.satfinite.e2m1x2.f16x2 %b2, %r10;\n" +
    "  cvt.rn.satfinite.e2m1x2.f16x2 %b3, %r11;\n" +
    "  mov.b16 %h3, {%b2, %b3};\n" +
    "  cvt.u32.u16 %r20, %h3;\n  mov.u32 %r21, 0;\n")
kernels["Roundtrip_e4m3_f16"] = (
    decode("e4m3", "f16") +
    "  cvt.rn.satfinite.e4m3x2.f16x2 %h3, %r10;\n" +
    "  cvt.rn.satfinite.e4m3x2.f16x2 %h4, %r11;\n" +
    "  mov.b32 %r20, {%h3, %h4};\n  mov.u32 %r21, 0;\n")

summary = {"kernels": list(kernels), "targets": {}, "direct_cvt": {}}
for target in ("sm_100a", "sm_110a"):
    text = f".version 9.4\n.target {target}\n.address_size 64\n"
    text += "\n".join(PREFIX.replace("NAME", name) + body + SUFFIX
                      for name, body in kernels.items())
    stem = "native-" + target
    ptx = ROOT / "assembly" / (stem + ".ptx")
    cubin = ptx.with_suffix(".cubin")
    ptx.write_text(text)
    built = command([PTXAS, "--verbose", "--gpu-name=" + target,
                     "--output-file", cubin, ptx], stem)
    summary["targets"][target] = {"returncode": built.returncode}
    if built.returncode == 0:
        assert "warning" not in built.stderr.lower()
        dis = command([DISASM, "--print-code", "--print-instruction-encoding",
                       cubin], stem + "-sass")
        assert dis.returncode == 0 and not dis.stderr
        summary["targets"][target].update({
            "cubin_sha256": hashlib.sha256(cubin.read_bytes()).hexdigest(),
            "conversion_and_multiply_SASS": [line.strip() for line in
                dis.stdout.splitlines() if re.search(r"\b(F2FP|F2F|HMUL2|HFMA2|QMUL4)\b", line)],
        })
    # PTX does not document this direct conversion. Check its acceptance,
    # without guessing or executing undocumented SASS encodings.
    direct = (f".version 9.4\n.target {target}\n.address_size 64\n" +
        PREFIX.replace("NAME", "Direct_e2m1_e4m3") +
        "  cvt.rn.satfinite.e4m3x2.e2m1x2 %h3, %b0;\n" +
        "  cvt.rn.satfinite.e4m3x2.e2m1x2 %h4, %b1;\n" +
        "  mov.b32 %r20, {%h3, %h4};\n  mov.u32 %r21, 0;\n" + SUFFIX)
    direct_ptx = ROOT / "assembly" / ("direct-" + target + ".ptx")
    direct_ptx.write_text(direct)
    attempt = command([PTXAS, "--verbose", "--gpu-name=" + target,
                       "--output-file", direct_ptx.with_suffix(".cubin"),
                       direct_ptx], "direct-" + target)
    summary["direct_cvt"][target] = {
        "returncode": attempt.returncode, "stderr": attempt.stderr}
(ROOT / "preparation/compile-result.json").write_text(
    json.dumps(summary, indent=2) + "\n")
print(json.dumps(summary, indent=2))

"""Capture environment and library identities without accessing the GPU."""

import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys


def snapshot():
    names = ("PATH", "LD_LIBRARY_PATH", "CUDA_HOME", "CUDA_PATH",
             "CUDA_VISIBLE_DEVICES", "CUDA_MODULE_LOADING", "CUDA_FORCE_PTX_JIT",
             "CUDA_DISABLE_PTX_JIT", "CUDA_CACHE_DISABLE", "CUDA_CACHE_PATH")
    value = {"environment": {name: os.environ.get(name) for name in names}}
    value["tools"] = {}
    for name in ("nvcc", "ptxas"):
        path = Path(shutil.which(name))
        value["tools"][name] = {
            "path": str(path), "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            "version": subprocess.check_output([str(path), "--version"], text=True),
        }
    value["cuda_links"] = {str(path): str(path.resolve())
                           for path in sorted(Path("/usr/local").glob("cuda*"))}
    driver = Path("/usr/lib/aarch64-linux-gnu/libcuda.so.1").resolve()
    value["driver"] = {"path": str(driver), "sha256": hashlib.sha256(
        driver.read_bytes()).hexdigest()}
    return value


if __name__ == "__main__":
    Path(sys.argv[1]).write_text(json.dumps(snapshot(), indent=2) + "\n")

