"""Generate exhaustive finite scalar coverage and exact packed references."""

import hashlib
import json
import math
from pathlib import Path
import struct

ROOT = Path(__file__).resolve().parent
DATA = ROOT / "data"
MAGNITUDES = (0, 0.5, 1, 1.5, 2, 3, 4, 6)


def fp4(code):
    return math.copysign(MAGNITUDES[code & 7], -1 if code & 8 else 1)


def fp8(code):
    exponent, mantissa = (code & 127) >> 3, code & 7
    magnitude = (math.ldexp(mantissa, -9) if exponent == 0 else
                 math.ldexp(1 + mantissa / 8, exponent - 7))
    return math.copysign(magnitude, -1 if code & 128 else 1)


LEVELS = [fp8(code) for code in range(127)]
SCALES = list(range(127)) + list(range(128, 255))


def scaled(fp4_code, scale_code):
    magnitude = abs(fp4(fp4_code) * fp8(scale_code))
    rounded = min(range(127), key=lambda c: (abs(LEVELS[c] - magnitude), c & 1))
    sign = ((fp4_code & 8) << 4) ^ (scale_code & 128)
    return rounded | sign


def bits16(value, fmt):
    if fmt == "f16":
        return struct.unpack("<H", struct.pack("<e", value))[0]
    bits = struct.unpack("<I", struct.pack("<f", value))[0]
    assert bits & 65535 == 0
    return bits >> 16


def pack_codes(codes, width):
    return sum(code << (width * i) for i, code in enumerate(codes))


def pack_values(values, fmt):
    return struct.pack("<4H", *(bits16(value, fmt) for value in values))


def sha(data):
    return hashlib.sha256(data).hexdigest()


# Each product uses at most six significant bits and lies within both formats.
# Verify every scalar pair, including the signs of exact and underflowed zeros.
for code in range(16):
    for scale in SCALES:
        value = fp4(code) * fp8(scale)
        half = struct.unpack("<e", struct.pack("<H", bits16(value, "f16")))[0]
        bf = struct.unpack("<f", struct.pack("<I", bits16(value, "bf16") << 16))[0]
        assert struct.pack("<d", half) == struct.pack("<d", value)
        assert struct.pack("<d", bf) == struct.pack("<d", value)
assert scaled(7, 126) == 126 and scaled(15, 126) == 254
assert scaled(1, 1) == 0 and scaled(9, 1) == 128
assert scaled(8, 128) == 0 and scaled(0, 128) == 128

vectors = [([2, 3, 10, 7], [0x38, 0x40, 0x30, 0x20])]
for scale in SCALES:
    for base in (0, 4, 8, 12):
        for rotation in range(4):
            vectors.append(([base + (lane + rotation) % 4 for lane in range(4)],
                            [scale] * 4))
for i in range(64):
    vectors.append(([(i * 7 + lane * 3) % 16 for lane in range(4)],
                    [SCALES[(i * 17 + lane * 29) % 254] for lane in range(4)]))
assert len(vectors) == 4129
coverage = {(lane, a, s) for codes, scales in vectors
            for lane, (a, s) in enumerate(zip(codes, scales))}
assert len(coverage) == 4 * 16 * 254
inputs = b"".join(struct.pack("<II", pack_codes(codes, 4), pack_codes(scales, 8))
                  for codes, scales in vectors)
(DATA / "inputs.bin").write_bytes(inputs)
kernels = json.loads((ROOT / "preparation/compile-result.json").read_text())["kernels"]
outputs = {}
for name in kernels:
    records = []
    for codes, scales in vectors:
        if name.startswith("Decode_"):
            _, kind, fmt = name.split("_")
            values = [fp4(c) for c in codes] if kind == "e2m1" else [fp8(s) for s in scales]
            record = pack_values(values, fmt)
        elif name.startswith("Roundtrip_"):
            kind = name.split("_")[1]
            value = pack_codes(codes, 4) if kind == "e2m1" else pack_codes(scales, 8)
            record = struct.pack("<II", value, 0)
        else:
            value = pack_codes([scaled(c, s) for c, s in zip(codes, scales)], 8)
            record = struct.pack("<II", value, 0)
        records.append(record)
    blob = b"".join(records)
    path = DATA / (name + ".expected.bin")
    path.write_bytes(blob)
    outputs[name] = {"sha256": sha(blob), "bytes": len(blob),
                     "first_output_hex": blob[:8].hex()}
assert outputs["Scaled_f16"]["sha256"] == outputs["Scaled_bf16"]["sha256"]
summary = {
    "packed_vectors_per_kernel": len(vectors), "scalar_values_per_kernel": 4 * len(vectors),
    "unique_scalar_pairs": 16 * 254, "unique_lane_scalar_pairs": len(coverage),
    "coverage": "all 16 E2M1 codes x all 254 finite signed E4M3 scale codes in every lane",
    "extra_vectors": "one smoke vector and 64 mixed-lane vectors",
    "nan_scales": "excluded; 0x7f and 0xff are NaN, not finite NVFP4 scales",
    "positive_NVFP4_scale_contract": "covered fully; signed scales also tested",
    "exact_intermediate_check": "all 4064 scalar products exactly representable in f16 and bf16, including signed zero",
    "rounding": "enumerate finite E4M3 outputs; nearest/even; sign-preserving satfinite",
    "self_checks": "PASS", "input_sha256": sha(inputs), "outputs": outputs,
}
(ROOT / "preparation/oracle.json").write_text(json.dumps(summary, indent=2) + "\n")
print(json.dumps({k: v for k, v in summary.items() if k != "outputs"}))

