namespace {

void Check(CUresult result, const char* api) {
  if (result == CUDA_SUCCESS) {
    std::cout << "{\"event\":\"cuda_success\",\"api\":" << std::quoted(api)
              << "}" << std::endl;
    return;
  }
  const char* name = "unknown";
  const char* description = "unknown";
  cuGetErrorName(result, &name);
  cuGetErrorString(result, &description);
  std::cout << "{\"event\":\"cuda_error\",\"api\":" << std::quoted(api)
            << ",\"code\":" << result << ",\"name\":" << std::quoted(name)
            << ",\"description\":" << std::quoted(description) << "}"
            << std::endl;
  std::_Exit(20);
}

std::vector<char> Read(const char* path) {
  std::ifstream file(path, std::ios::binary);
  return std::vector<char>((std::istreambuf_iterator<char>(file)), {});
}

}  // namespace

int main(int argc, char** argv) {
  if (argc != 6) return 2;
  const std::vector<char> image = Read(argv[1]);
  const std::vector<char> inputs = Read(argv[3]);
  const std::vector<char> expected = Read(argv[4]);
  if (image.size() < 64 || inputs.size() != expected.size() ||
      inputs.empty() || inputs.size() % 8 != 0 || inputs.size() > 1048576) {
    return 2;
  }
  const uint32_t count = inputs.size() / 8;
  Check(cuInit(0), "cuInit");
  int driver_version = 0;
  Check(cuDriverGetVersion(&driver_version), "cuDriverGetVersion");
  CUdevice device;
  Check(cuDeviceGet(&device, 0), "cuDeviceGet");
  char name[256] = {};
  Check(cuDeviceGetName(name, sizeof(name), device), "cuDeviceGetName");
  int major = 0;
  int minor = 0;
  Check(cuDeviceGetAttribute(&major,
                            CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR,
                            device), "cuDeviceGetAttribute-major");
  Check(cuDeviceGetAttribute(&minor,
                            CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR,
                            device), "cuDeviceGetAttribute-minor");
  std::cout << "{\"event\":\"device\",\"name\":" << std::quoted(name)
            << ",\"major\":" << major << ",\"minor\":" << minor
            << ",\"driver_version\":" << driver_version << "}" << std::endl;
  if (major != 11 || minor != 0) return 3;
  CUcontext context;
  Check(cuCtxCreate(&context, nullptr, CU_CTX_SCHED_BLOCKING_SYNC, device),
        "cuCtxCreate");
  std::this_thread::sleep_for(std::chrono::milliseconds(1250));
  CUmodule module;
  Check(cuModuleLoadDataEx(&module, image.data(), 0, nullptr, nullptr),
        "cuModuleLoadDataEx");
  CUfunction function;
  Check(cuModuleGetFunction(&function, module, argv[2]), "cuModuleGetFunction");
  int version = 0;
  Check(cuFuncGetAttribute(&version, CU_FUNC_ATTRIBUTE_BINARY_VERSION, function),
        "cuFuncGetAttribute-binary");
  std::cout << "{\"event\":\"binary_version\",\"value\":" << version
            << "}" << std::endl;
  if (version != 110) return 3;
  CUdeviceptr device_inputs;
  CUdeviceptr allocation;
  Check(cuMemAlloc(&device_inputs, inputs.size()), "cuMemAlloc-inputs");
  Check(cuMemAlloc(&allocation, expected.size() + 32), "cuMemAlloc-output");
  CUdeviceptr output = allocation + 16;
  std::vector<char> actual(expected.size() + 32, static_cast<char>(0xa5));
  Check(cuMemcpyHtoD(device_inputs, inputs.data(), inputs.size()),
        "cuMemcpyHtoD-inputs");
  Check(cuMemcpyHtoD(allocation, actual.data(), actual.size()),
        "cuMemcpyHtoD-canaries");
  uint32_t argument_count = count;
  void* params[] = {&device_inputs, &output, &argument_count};
  Check(cuLaunchKernel(function, (count + 127) / 128, 1, 1, 128, 1, 1, 0,
                       nullptr, params, nullptr), "cuLaunchKernel");
  Check(cuCtxSynchronize(), "cuCtxSynchronize");
  Check(cuMemcpyDtoH(actual.data(), allocation, actual.size()), "cuMemcpyDtoH");
  std::ofstream actual_file(argv[5], std::ios::binary);
  actual_file.write(actual.data(), static_cast<std::streamsize>(actual.size()));
  actual_file.close();
  if (!actual_file) return 4;
  uint32_t mismatches = 0;
  for (uint32_t i = 0; i < count; ++i) {
    bool matches = true;
    for (int byte = 0; byte < 8; ++byte) {
      matches = matches && actual[16 + i * 8 + byte] == expected[i * 8 + byte];
    }
    if (!matches) {
      if (mismatches < 16) {
        std::cout << "{\"event\":\"mismatch\",\"index\":" << i << "}"
                  << std::endl;
      }
      ++mismatches;
    }
  }
  bool guards_ok = true;
  for (int i = 0; i < 16; ++i) {
    guards_ok = guards_ok && actual[i] == static_cast<char>(0xa5) &&
                actual[16 + expected.size() + i] == static_cast<char>(0xa5);
  }
  Check(cuMemFree(device_inputs), "cuMemFree-inputs");
  Check(cuMemFree(allocation), "cuMemFree-output");
  Check(cuModuleUnload(module), "cuModuleUnload");
  Check(cuCtxDestroy(context), "cuCtxDestroy");
  std::cout << "{\"event\":\"completed\",\"kernel\":" << std::quoted(argv[2])
            << ",\"vectors\":" << count << ",\"mismatches\":" << mismatches
            << ",\"guards_ok\":" << (guards_ok ? "true" : "false") << "}"
            << std::endl;
  return mismatches || !guards_ok ? 30 : 0;
}

